// IELTS Speaking Part 3: 50 discussion sets, one for each Part 2 cue card theme (same order and same sub as
// speaking-part2.js), each with three abstract questions and a model answer to each. All original.
const SUBS = ['person', 'person', 'person', 'person', 'person', 'person', 'person', 'person', 'place', 'place', 'place', 'place', 'place', 'place', 'place', 'place', 'object', 'object', 'object', 'object', 'object', 'object', 'object', 'event', 'event', 'event', 'event', 'event', 'event', 'event', 'event', 'experience', 'experience', 'experience', 'experience', 'experience', 'experience', 'experience', 'activity', 'activity', 'activity', 'activity', 'activity', 'activity', 'media', 'media', 'media', 'media', 'media', 'media'];
const P = [];
const add = (theme, level, qa) => P.push({ theme, level, qa });

// ---------- person ----------
add('teachers and learning', 3, [
  ['What qualities make a good teacher?', `I'd say patience and the ability to explain things in different ways are the most important. A teacher who is brilliant but can only explain one way will lose half the class. Knowledge matters too, of course, but I've had very clever teachers who were poor at teaching. So I'd put communication ahead of expertise, although the best teachers obviously have both.`],
  ['Do you think technology will replace teachers in the future?', `I don't think it will replace them completely, although it will change their role. Software can already give instant feedback and repeat explanations as often as a student needs. However, a teacher notices when a child is upset or losing motivation, and no program does that well. I'd expect teachers to spend less time on routine marking and more on guiding and inspiring students.`],
  ['Should students be allowed to choose what they study at school?', `To some extent, yes. If students choose some subjects, they're likely to be more motivated, and they may discover talents early. On the other hand, young teenagers often don't know what will be useful, so I think the basics, such as maths, a language and science, should be compulsory. A balance between the two seems best, with more freedom as students get older.`]]);
add('family role models', 3, [
  ['Why do children often admire their relatives?', `Mainly because relatives are the people they see most often during their early years. Children copy what they see, so a grandmother who works hard or an uncle who tells good stories becomes a hero. Also, relatives give love without conditions, which creates a strong emotional bond. As children grow older, though, they usually start to look outside the family for role models.`],
  ['Are family ties as strong today as they were in the past?', `In some ways they're weaker, because people move to other cities or countries for work and see their families less. In the past, several generations often lived together. On the other hand, technology means that families can now stay in touch daily by video, which wasn't possible before. So I'd say the ties are different rather than weaker, though they require more effort.`],
  ['Who should be responsible for caring for elderly people, families or the government?', `I think the responsibility should be shared. Families can offer love and company, which no institution can replace. But caring for someone with serious health needs is a full-time job, and many families cannot manage it financially. Therefore, governments should provide funding, nurses and care homes, so that families can focus on emotional support instead of being exhausted.`]]);
add('friendship and social skills', 3, [
  ['How do people usually make friends as adults?', `Mostly through shared activities, such as work, sports clubs or hobby groups. Repeated contact matters more than anything else, because friendships develop when you see the same people regularly. Adults have less free time than students, so it takes longer. Nowadays, online communities also help, although many people feel that meeting in person is still better.`],
  ['Is it more important to have many friends or a few close friends?', `For me, a few close friends are far more valuable. With them you can be honest about your problems, and they will be there when things go wrong. Having a wide circle can be fun and useful for networking, but it rarely gives the same emotional support. Quality tends to matter more than quantity, though everyone is different.`],
  ['Do you think social skills can be taught?', `Yes, I believe so, at least partly. Some people are naturally outgoing, but skills like listening, starting a conversation and handling disagreement can be practised. Schools could include role-play and group projects to help. The key is to start young, because shy children who get no support may avoid people for years.`]]);
add('fame and admiration', 3, [
  ['Why are some people famous in the first place?', `There are several routes. Some achieve fame through talent or achievement, such as athletes, scientists or actors. Others become famous because of luck or because of media attention, like people whose video goes viral. In my opinion, the first type deserves it more, although in practice the media often gives more attention to entertainment than to science.`],
  ['Do you think famous people are good role models for young people?', `Some are, but it depends on the person. A sports star who trains for years teaches discipline and teamwork. However, many celebrities are famous mostly for their lifestyle, which can give young people unrealistic ideas about money and appearance. I'd encourage young people to look for role models among people whose work they truly respect, not just those with many followers.`],
  ['How has social media changed the nature of fame?', `It has made fame much more accessible, since anyone can reach a huge audience without a studio or an agent. That's positive because talented people can be discovered. The downside is that fame can be short-lived and very public, so people may face criticism or pressure. As a result, many influencers experience stress that older celebrities were protected from.`]]);
add('neighbours and community', 3, [
  ['Why do people in big cities often not know their neighbours?', `Mainly because of how busy and mobile life is. People work long hours, travel a lot and move house frequently, so they never build any connection. In apartment blocks, you can live next to someone for years without meeting them. In villages, by contrast, you see the same people every day, so relationships form naturally.`],
  ['How can communities be made stronger?', `Shared spaces and events are the most effective tools. Local festivals, community gardens or even a notice board in the lobby give people a reason to talk. Councils could also support small clubs for older people and families. When people interact repeatedly, trust grows, and then they begin to help each other without being asked.`],
  ['Do you think the internet has weakened local communities?', `In some ways it has, since people spend their evenings online instead of chatting on the doorstep. However, it has also made new kinds of community possible. Neighbourhood groups on social media are used to share information, borrow tools or warn about crime. So I'd say the internet changes the way communities work rather than simply destroying them.`]]);
add('giving and taking advice', 3, [
  ['Who do people usually ask for advice?', `It depends on the type of problem. For personal matters, most people turn to close friends or family, because they trust them. For careers or money, they'd rather ask somebody with experience, like a mentor. These days, many people also look for advice online, which is quick but not always reliable, so it's important to check the source.`],
  ['Is it always a good idea to follow advice from older people?', `Not always. Older people have more experience, so their advice is often valuable, especially about relationships and money. However, the world changes quickly, and what worked thirty years ago may not apply to today's job market. I think the best approach is to listen carefully, consider the reasons behind the advice and then decide for yourself.`],
  ['Why do some people find it difficult to accept advice?', `Often it's about pride. Accepting advice can feel like admitting that you don't know something, which makes some people defensive. Others may have received unwanted advice in the past that was critical rather than helpful. How the advice is given matters, too. If it sounds like an order, people resist it, whereas a suggestion is easier to accept.`]]);
add('interesting jobs', 3, [
  ['What makes a job interesting?', `For most people, it's variety and a sense of purpose. A job where every day is slightly different keeps your mind active, and it's even better if you feel that your work helps someone. Of course, an interesting job isn't the same as a well-paid one. Some people accept lower pay for work they find meaningful, whereas others prefer security, so it's a personal choice.`],
  ['Do you think salary or job satisfaction is more important?', `I'd say that both matter, but satisfaction becomes more important once your basic needs are met. Without enough money, you'll worry constantly, so salary can't be ignored. However, people who dislike their work often feel stressed even with a high salary. If I had to choose, I'd accept a slightly lower income for a job that I enjoyed.`],
  ['Which jobs will be most important in the future?', `I expect jobs in health care, renewable energy and technology to grow, as populations age and countries try to reduce emissions. Jobs that require human skills, like teaching and caring, will probably remain important too, because machines can't easily copy empathy. On the other hand, repetitive jobs in offices and factories are likely to decline as automation advances. For example, many bank clerks and cashiers have already seen their roles change.`]]);
add('historical figures', 4, [
  ['Why is it important to study the lives of people from history?', `Because they show us how ideas and decisions shaped the world we live in. We can learn from their successes and from their mistakes without having to repeat them. Moreover, biographies make history more human. It's easier to remember dates and events when they're attached to a person with hopes and fears.`],
  ['Do you think history is taught well in schools?', `In many places, it's taught as a list of dates and battles, which students find dull and soon forget. A better approach would be to focus on stories, sources and questions, such as "why did this happen?" That develops critical thinking, not just memory. Some schools are already doing this with projects and museum visits, and the results seem encouraging. Even so, a well-prepared teacher is still the most important factor.`],
  ['Are today\'s leaders as influential as those of the past?', `It's hard to say, since we're too close to the present to judge. Today's leaders face more scrutiny from the media, and power is spread across companies, institutions and citizens, so individuals may have less personal influence. On the other hand, decisions about technology or climate can affect the whole planet, so their impact may in fact be greater. For instance, one decision about energy policy can shape the climate for decades.`]]);

// ---------- place ----------
add('relaxing places', 2, [
  ['Why do people need places where they can relax?', `Because constant stress is bad for both physical and mental health. A relaxing place, whether it's a park or a quiet cafe, gives the mind a chance to recover. It helps people to concentrate better afterwards, too. In busy cities, where space is limited, such places are even more valuable.`],
  ['Do people in your country spend enough time relaxing?', `I think many don't, particularly in cities. Working hours are long, and people spend their free time on phones, which isn't truly restful. Some are starting to realise this, and activities like yoga and walking are becoming popular. But there's still a culture of being busy, which makes relaxing feel like a waste of time.`],
  ['Should cities provide more green spaces?', `Yes, definitely. Green spaces improve air quality, lower temperatures in summer and give people somewhere to exercise. They also benefit mental health. The only difficulty is cost, because land in city centres is expensive. However, I think governments should treat parks as essential infrastructure, just like roads and hospitals.`]]);
add('holiday destinations and tourism', 3, [
  ['What are the advantages of travelling abroad?', `You get to experience different cultures, languages and foods, which broadens your mind. You also learn to be more independent, because you have to solve small problems on your own. In addition, travel can inspire new ideas for work or study. The main disadvantages are cost and the environmental impact of flying.`],
  ['Is tourism always good for the places that people visit?', `Not always. It brings money and jobs, which is a clear benefit, particularly for small economies. But too many visitors can damage historic sites, push up prices for residents and create litter and noise. Some cities now limit the number of tourists, which seems sensible, so that the benefits do not destroy what people come to see.`],
  ['How might holidays change in the next fifty years?', `I think people will travel in more environmentally friendly ways, perhaps by high-speed train or electric aircraft. Virtual reality might also let people explore places without going there, although I doubt it will replace the real thing. Probably, we'll see a shift towards fewer but longer trips, as people become more aware of carbon emissions. Of course, this may be less true for people who have to travel for work.`]]);
add('heritage and historical sites', 3, [
  ['Why do governments spend money on preserving historic sites?', `Because they're part of a nation's identity and they teach people about the past. Historic sites also attract tourists, so they can produce income. Once a building is lost, it can't be replaced. However, the cost can be high, so governments must weigh it against other needs, like schools and hospitals.`],
  ['Should tourists be charged more than local people to visit historical sites?', `I think it's reasonable. Locals have often contributed through taxes, and a lower price encourages them to visit and appreciate their heritage. Tourists, who are usually spending more on the trip anyway, can afford a higher fee, and the extra money helps to pay for maintenance. The difference shouldn't be so large that it feels unfair, though.`],
  ['Do young people take enough interest in history?', `It varies. Many find history boring when it's taught from a textbook, but they get excited by interactive exhibitions or films. If museums and sites use technology, such as augmented reality, they can reach younger audiences. So I don't think young people are uninterested, but traditional methods often fail to engage them.`]]);
add('eating out and food culture', 2, [
  ['Why do people enjoy eating in restaurants?', `There are social and practical reasons. It's a pleasant way to meet friends, and you don't have to cook or wash up. Restaurants also offer food that people can't easily make at home, such as dishes from other countries. For many, it's simply a treat after a long week.`],
  ['Has the way people eat changed in recent years?', `Yes, a lot. People eat out more, order food through apps and often eat alone while looking at a screen. At the same time, there's more interest in healthy and vegetarian options. So we have two opposite trends: more convenience, and more awareness of what we eat.`],
  ['Do you think fast food will disappear in the future?', `I doubt it will disappear, because it's fast and cheap, and people with busy lives will always want that. However, I expect it to change, with healthier menus and less packaging, as customers and governments demand it. Some chains already offer plant-based burgers, which would have been unthinkable twenty years ago. Even so, burgers and fries will probably stay the most popular choice for a long time.`]]);
add('nature and conservation', 3, [
  ['Why is it important to protect natural areas?', `They provide clean air and water, and they are home to species that would otherwise disappear. They also have value for health, as people feel calmer in nature. Once a forest or wetland is destroyed, it can take hundreds of years to recover, so prevention is far cheaper than repair. A good example is the way wetlands protect towns from floods for free.`],
  ['Should people be allowed to visit national parks freely?', `I think so, within limits. Visiting nature helps people to care about it, so access builds support for conservation. But if there are too many visitors, they can damage the paths and disturb animals. A sensible system would limit numbers on busy days and require visitors to follow rules, such as taking their litter home.`],
  ['What can individuals do to help protect the environment?', `Small habits make a difference when millions of people share them, such as reducing waste, using public transport and saving energy. Individuals can also vote and support organisations that protect nature. Having said that, companies and governments have much greater influence, so individual action should be combined with pressure for larger changes. Otherwise, the burden falls on ordinary people who have the least power.`]]);
add('architecture and design', 3, [
  ['Why do some buildings become famous?', `Often because of an unusual design or because of what happened inside them. A landmark such as a tower or an opera house becomes a symbol of the city. Age also plays a part, as old buildings gain value as they survive. Sometimes a famous architect's name is enough to attract attention.`],
  ['Should new buildings in a city match the style of the old ones?', `It depends. In historic areas, I believe new buildings should respect the surrounding style, so the character of the place isn't lost. But in other districts, modern design can show that a city is alive and creative. The ideal is a mixture, where new buildings are carefully planned and sit comfortably beside the old.`],
  ['Is it more important for a building to be beautiful or useful?', `Ideally both, but if I had to choose, I'd say useful, since a building that doesn't work well for its occupants is a failure however it looks. However, beauty has a real effect on how people feel, so I wouldn't dismiss it. Good design can achieve both, as many railway stations show. Some of the best stations are both beautiful and easy to use, which proves it is possible.`]]);
add('social spaces', 2, [
  ['Why do people like to meet in public places rather than at home?', `Because public places are neutral and convenient. You don't have to clean your house or prepare food, and you can leave whenever you wish. Cafes and parks also offer a lively atmosphere. For first meetings, a public place feels safer and more comfortable for everyone.`],
  ['Are shopping centres good places for young people to spend time?', `They have advantages, since they're safe, warm and have lots to do. However, they also encourage spending money, which not all teenagers can afford. I think towns should offer free alternatives, such as youth centres, sports grounds and libraries, so young people have a choice. Otherwise, the mall becomes the only option by default.`],
  ['Will online communication replace face-to-face meetings in the future?', `It will probably replace some of them, especially for work, where video calls save travel time. But I think people will always want to meet in person for important or emotional occasions. A video call can't fully replace a hug or a shared meal, so both will continue. In my own life, I use video calls for work and travel for weddings.`]]);
add('urban development and preservation', 4, [
  ['Why do old buildings sometimes get demolished?', `Mostly for economic reasons. Land in cities is valuable, and developers can often make more money from a new apartment block than from an old building. Sometimes the old building is genuinely unsafe or too expensive to repair. The problem is that once it's gone, a piece of the city's history disappears.`],
  ['Who should decide what is preserved, the government or local people?', `Ideally both. Governments can set rules to protect important sites and have the money to enforce them. But local people understand which places matter emotionally to the community. A good process would let residents suggest sites, while experts judge their historical value, and then both sides would agree on a plan.`],
  ['Can modern cities keep their traditions and still develop?', `Yes, but it requires planning. Cities can build new districts for business and housing, while keeping their historic centres and markets alive. Some cities have done this successfully by reusing old buildings as cafes, shops or studios. The risk comes when growth is left entirely to the market, since profit rarely protects tradition.`]]);

// ---------- object ----------
add('everyday objects and consumerism', 2, [
  ['Why do people become attached to ordinary objects?', `Because objects carry memories. A watch from a grandfather or a mug from a first job reminds us of a time or a person. Some objects also become part of our daily habits, so we feel uncomfortable without them. The value is emotional rather than financial.`],
  ['Do you think people buy too many things nowadays?', `Yes, in many countries. Advertising and online shopping make it easy to buy impulsively, and cheap prices encourage us to replace things rather than repair them. This creates a lot of waste. A growing number of people are trying to live with less, and I think that's a healthy trend.`],
  ['Should products be designed to last longer?', `I believe so. Longer-lasting products save customers money and reduce waste. Companies may prefer shorter life cycles because they sell more, so regulation might be needed, such as requiring spare parts to be available. In the long run, a reputation for quality can also be good for business.`]]);
add('gifts and giving', 3, [
  ['Why do people give gifts on special occasions?', `It's a way of showing that we care. A gift marks the occasion and makes the other person feel remembered. In many cultures, it also follows tradition and builds social bonds. Some people feel obliged to give gifts, which can turn a kind gesture into a duty.`],
  ['Is it better to give practical gifts or surprising ones?', `I think it depends on the person and the occasion. Practical gifts show that you've thought about their needs, but they can feel dull. A surprise gift can create a lovely moment, but there's a risk that it won't be useful. My preference is a combination, something useful with a personal touch.`],
  ['Do you think the habit of giving gifts has become too commercial?', `To some extent, yes. Companies promote certain days as occasions for spending money, and people feel pressure to buy expensive items. However, many people still value homemade or thoughtful presents. If we focus on the meaning rather than the price, gift-giving can remain a positive tradition.`]]);
add('old things and memories', 3, [
  ['Why do people keep old objects?', `Mostly for sentimental reasons. An old object links us to people and events that are important to us, especially after relatives have passed away. Some people keep things because they might be valuable or useful one day. Others find it hard to throw things away, which can lead to clutter.`],
  ['Do you think antiques are worth the money people pay for them?', `It depends on what you value. If an antique is rare and in good condition, its price can be justified as an investment. But much of the price comes from fashion, which can change. I'd rather spend money on something I'd use and enjoy, though I understand the appeal.`],
  ['Is it important to teach children about their family history?', `I think so, as it gives them a sense of identity and belonging. Stories about grandparents' lives show children how much has changed and how people overcame difficulties. Objects, photographs and recipes can make these stories more real. It's a simple way to strengthen family relationships, too.`]]);
add('technology in daily life', 3, [
  ['How has technology changed the way people work?', `Greatly. Many people can now work from home, communicate instantly and automate tasks that used to take hours. This has increased productivity and flexibility. On the downside, workers are often expected to be available at all hours, so the border between work and home life has become blurred.`],
  ['Are older people able to keep up with new technology?', `Many can, but they may need more support and patience. Some feel intimidated by constant updates and fear making mistakes. Others learn very quickly when someone shows them step by step. I think it's important that essential services, like banking, still offer non-digital options so that nobody is excluded.`],
  ['Will people become too dependent on technology?', `There's a real risk. We already rely on maps for navigation and on search engines for facts, and some skills, such as remembering phone numbers, have weakened. The danger is greatest when systems fail. I think it's sensible to keep basic skills and to have backup plans, while still enjoying the benefits.`]]);
add('reading and literature', 3, [
  ['Do you think reading habits are changing?', `Yes. People still read a lot, but much of it is short text on screens, such as messages and articles, rather than long books. Fewer young people read novels for pleasure, partly because phones offer so many alternatives. However, audiobooks and e-readers are making books accessible in new ways.`],
  ['Why do some people prefer to read the same book several times?', `A familiar book is comforting, and you can notice details that you missed the first time. Also, we change as we grow older, so the same story can mean something different at another stage of life. For some people, rereading is like meeting an old friend. Having said that, it doesn't suit everyone, because some readers always want something new.`],
  ['Should schools encourage children to read more?', `Absolutely. Reading improves vocabulary, concentration and imagination, and it helps with every other subject. Schools can encourage it by giving children a choice of books rather than forcing certain titles, and by giving time for quiet reading. Parents also play a big role by reading aloud with young children.`]]);
add('fashion and clothing', 2, [
  ['Why do people care about what they wear?', `Clothes communicate who we are, or who we want to be. They affect how others see us, so people dress carefully for interviews or special occasions. Clothes can also affect how we feel. When I wear something that fits well, I feel more confident.`],
  ['Is fast fashion a problem?', `Yes, I think so. Cheap clothes encourage people to buy more than they need and throw things away after a few wears, which creates a huge amount of waste. Production often uses a lot of water and can involve poor working conditions. Buying fewer, better items and choosing second-hand clothes would help.`],
  ['Should schools and companies have dress codes?', `A simple dress code can be useful. Uniforms reduce competition between students about expensive brands and create a sense of belonging. In workplaces, some dress standards are reasonable for safety or customer service. But rules that are too strict can limit self-expression, so there should be a balance.`]]);
add('inventions and progress', 4, [
  ['Which invention do you think has had the greatest impact in the last hundred years?', `I'd say the internet, because it has transformed communication, business, education and entertainment all at once. Penicillin and other medicines are strong candidates too, since they have saved millions of lives. But the internet affects almost every aspect of modern life, so I'd rank it first. Admittedly, it's hard to compare it fairly with a medicine that saves lives directly.`],
  ['Do inventions always make life better?', `Not always. Many have both benefits and costs. The car gave people freedom but also caused pollution and accidents, and social media connects us but may harm mental health. How an invention is used matters as much as the invention itself, which is why regulation and education are so important.`],
  ['Should governments fund scientific research, or should it be left to companies?', `I believe that governments should play a major role, since basic research can take decades to produce results and companies tend to prefer short-term profit. Many important discoveries, such as the early internet, came from public funding. Companies can then develop the ideas into products, so a partnership works best. Companies may fund the later stages, where the profit is more certain.`]]);

// ---------- event ----------
add('weddings and family celebrations', 2, [
  ['Why are weddings so important in many cultures?', `They mark a major step in life and bring two families together. Weddings are also a chance for the whole community to celebrate and to pass on traditions through music, clothing and food. For many families, they're among the most important events of the year. Naturally, the details vary from one culture to another.`],
  ['Do you think people spend too much money on weddings?', `In many cases, yes. Some couples go into debt for a single day, which seems unwise. The most memorable weddings I've been to weren't the most expensive, but the ones with warm and personal details. I think it's better to spend on a good start for married life, like a home.`],
  ['How have wedding traditions changed over time?', `They've become more individual. In the past, families often decided everything, whereas now couples plan their own ceremonies and may include elements from different cultures. Smaller weddings and outdoor ceremonies are more common. At the same time, many core traditions, such as exchanging rings, have survived.`]]);
add('busy lives and stress', 3, [
  ['Why are people so busy nowadays?', `Partly because of technology. We can be contacted at any time, so work follows us home. Costs of living are also high in many places, so people take extra jobs. Finally, there are so many options for entertainment and education that people try to fit in too much.`],
  ['What are the effects of stress on people?', `In the short term, stress can improve performance, but over a long period it leads to tiredness, poor sleep and even health problems like high blood pressure. It also affects relationships, as stressed people are often less patient. Taking breaks, exercising and talking to others can all help. For instance, a short walk at lunchtime can lower tension surprisingly well.`],
  ['What can companies do to reduce stress among employees?', `They can offer flexible hours, realistic deadlines and the option to work from home. Managers should encourage people to take holidays and avoid sending emails after hours. Providing mental health support is also worthwhile. Ultimately, a less stressed workforce is more productive, so it benefits the company too.`]]);
add('festivals and traditions', 3, [
  ['Why do festivals matter to a society?', `They give people a shared experience and strengthen community identity. Festivals pass traditions between generations and give people a break from routine. Many also have economic value, as they attract tourists and support local businesses. On the other hand, a festival that depends on tourists can lose its real character.`],
  ['Are traditional festivals losing their importance?', `In some places, yes. Young people move to cities and may treat festivals as just a day off. But in others, they're being revived, since people want to connect with their roots. Social media has even helped by spreading festivals to a global audience.`],
  ['Is it a good idea for tourists to attend local festivals?', `Generally yes, if they behave respectfully. It gives visitors a deeper understanding of the culture and brings income to the community. The risk is that a festival becomes a performance for tourists, losing its real meaning. Good organisation can prevent that, for instance by keeping some parts for locals only.`]]);
add('sport and competition', 3, [
  ['Why are sports events so popular?', `They combine excitement, skill and a sense of belonging. Supporting a team gives people a shared identity, and the uncertainty of the result keeps them watching. Major events also unite whole countries, which few other things can do. For example, a national team's victory can bring millions of strangers into the streets together.`],
  ['Should governments spend money on hosting big sporting events?', `It's a difficult question. Events like the Olympics bring pride, tourists and new facilities, but the costs are enormous and sometimes the stadiums are left unused. I think governments should host them only if the facilities will serve the community afterwards, and if the budget is realistic. Several cities have been left with huge debts, which is a warning for the future.`],
  ['Is competition good for children?', `In moderation, yes. It can teach children to cope with winning and losing and to work in a team. However, too much pressure can reduce enjoyment and cause anxiety. Coaches should therefore emphasise effort and improvement over results, particularly with young players.`]]);
add('helping others', 2, [
  ['Why do some people help strangers while others do not?', `Personality and upbringing play a part, as people who were taught to be kind tend to help. Circumstances matter too. In a crowd, people often assume that someone else will act, but when you're alone you feel more responsible. Fear or lack of time can also stop people from helping.`],
  ['Is it the government\'s job to help people in need, or the individual\'s?', `Both have a role. Governments can provide systems like health care and unemployment benefits that individuals cannot. But personal kindness fills gaps that systems miss, for example visiting a lonely neighbour. A society works best when public support and personal generosity go together.`],
  ['How can children be taught to help others?', `Mostly by example. If children see their parents helping, they will copy this behaviour. Schools can also organise community projects, such as cleaning a park or visiting a care home, so that children experience how good it feels to help. Praise for kind actions encourages the habit.`]]);
add('punctuality and time', 3, [
  ['Why is being on time important in some situations?', `Because it shows respect for other people's time. In business, delays cost money, and in services such as transport or health care, they can even be dangerous. For a job interview, arriving late creates a bad first impression. In social settings, however, people are usually more relaxed.`],
  ['Do you think people today are more or less punctual than in the past?', `It's difficult to say. Phones and calendar apps remind us of appointments, so in theory we should be more punctual. But the same technology lets us send a message saying we're late, so it feels less serious. I'd say that people are punctual for work but flexible for social events.`],
  ['How can cities reduce the problem of traffic delays?', `Better public transport is the most effective method, because it takes cars off the roads. Cities can also charge drivers to enter the centre, create cycle lanes and encourage flexible working hours so that everyone isn't travelling at the same time. A combination of measures works better than any single one. Remote working a few days a week, for instance, has already reduced rush-hour crowds in some cities.`]]);
add('sharing meals and food', 3, [
  ['Why is sharing meals important for families and friends?', `Meals give people time to talk without distractions. Sharing food is an ancient way of showing care and building trust. Families who eat together regularly tend to communicate better, and children often develop healthier eating habits. Of course, this assumes that the food is actually healthy.`],
  ['Do people eat together as often as in the past?', `Less often, I think. Work schedules, school activities and screens mean that many families eat at different times or in front of the television. Some families are now making rules, such as no phones at the table, to protect mealtimes. It doesn't always work, but even one shared meal a day helps.`],
  ['How do eating customs differ between cultures?', `Greatly. In some countries, people eat with their hands from shared dishes, while in others each person has a separate plate and cutlery. Customs about who is served first or what is polite to leave on the plate also vary. Learning them is a good way to show respect when travelling.`]]);
add('news and the media', 4, [
  ['Why do people follow the news?', `To understand what's happening around them and to make informed decisions, such as whom to vote for. For many, it's also about feeling connected to society. Some follow it from habit or curiosity, although too much news can cause anxiety. For this reason, many people choose to check the news only once or twice a day.`],
  ['Is the media reliable today?', `It varies widely. Established organisations usually check their facts, but competition for attention leads some outlets to exaggerate stories. Social media adds another challenge, since false information spreads quickly. Readers need to compare sources and be sceptical about shocking headlines.`],
  ['Should the news focus more on positive stories?', `I think there should be more balance. Negative stories are important, because people need to know about problems. But a constant stream of bad news can make people feel hopeless and disengaged. Reporting solutions and successes, as well as problems, would give a more accurate and more motivating picture.`]]);

// ---------- experience ----------
add('learning new skills', 3, [
  ['Why do some people learn new skills faster than others?', `Motivation is probably the biggest factor, because people who really want to learn will practise more. Previous experience helps too, since skills often overlap. A good teacher or method also makes a difference, and so does confidence. People who are afraid of mistakes often learn more slowly, as they avoid trying things out.`],
  ['Is it harder to learn new things as an adult than as a child?', `In some ways it is. Children are less self-conscious and have more free time, and their brains absorb languages and movements easily. Adults, however, can plan, understand explanations and connect new knowledge to what they already know. So adults may start slower but can progress efficiently if they are patient.`],
  ['Should schools teach practical skills as well as academic subjects?', `Yes, I think so. Skills such as cooking, first aid and managing money are used throughout life, but many students leave school without them. Academic subjects are still essential, so I wouldn't replace them. A balanced timetable, with some time for practical lessons, would prepare young people better for adult life.`]]);
add('patience and waiting', 3, [
  ['Why do some people find waiting difficult?', `We live in a culture of instant results, with fast food, same-day delivery and immediate messages, so we're less used to delays. Personality matters too, since some people are naturally more anxious. When the outcome is important, like exam results, the uncertainty makes waiting even harder. A person waiting for an exam result, for example, can think of little else.`],
  ['Is patience a quality that can be developed?', `I think so. Like a muscle, it improves with practice. Techniques such as breathing slowly, keeping busy and focusing on what you can control all help. Having experienced a long wait that ended well also teaches us that worrying isn't useful.`],
  ['How could public services reduce waiting times?', `They could use technology, for example online appointment systems and real-time information about queues. Hiring more staff at peak times would help, as would simplifying forms. Even when the wait can't be shortened, giving people accurate information about how long it will be makes it far more bearable. A simple text message saying that you are fourth in the queue changes the whole mood.`]]);
add('disagreement and communication', 4, [
  ['Why do people disagree with each other?', `Usually because they have different values, information or priorities. Sometimes the disagreement is really about misunderstanding, since people interpret the same words differently. Stress and tiredness make things worse. It's rarely just about the topic, because emotions and pride often become involved.`],
  ['What is the best way to resolve a conflict?', `In my view, listening first is the key. If each side explains its reasons without being interrupted, it's often possible to find common ground. It also helps to talk privately and calmly rather than in front of others. If that fails, a neutral person such as a mediator can help both sides.`],
  ['Is it healthy to avoid arguments completely?', `Not really. If people never express disagreement, resentment builds up and problems stay unsolved. Healthy disagreement can lead to better ideas, because different views are considered. The aim shouldn't be to avoid conflict, but to handle it respectfully.`]]);
add('trying new foods and cultures', 3, [
  ['Why are some people reluctant to try unfamiliar food?', `Often it's about fear of the unknown, or a bad past experience. Texture and smell can be off-putting, especially for children. Cultural habits also play a role, because we feel comfortable with the foods we grew up with. Trying small portions with friends usually helps.`],
  ['How has international travel changed what people eat?', `People bring back tastes from abroad, and migrants open restaurants that introduce their cuisines. As a result, dishes like sushi and curry are now common worldwide. This has widened choice, though it has also meant that some local traditions are being forgotten as global chains spread. Yet a few countries have protected them by giving them official recognition.`],
  ['Do you think traditional dishes will survive in the future?', `I think they will, but in a modified form. Many younger people are interested in their heritage and enjoy cooking traditional recipes at festivals. At the same time, fast food and convenience meals are replacing everyday cooking. Recording recipes and teaching children to cook would help preserve them.`]]);
add('crowds and city life', 3, [
  ['Why do some people enjoy being in crowds while others avoid them?', `It depends on personality. Outgoing people draw energy from the excitement of a crowd, while quieter people find it tiring and stressful. Past experiences also matter, because someone who has felt unsafe in a crowd will be more cautious. The occasion matters too, since a concert feels very different from a busy train.`],
  ['What problems do crowded cities face?', `The main ones are housing costs, traffic, pollution and pressure on services such as schools and hospitals. Noise and lack of green space can also affect people's wellbeing. To cope, cities can improve public transport, build more affordable homes and develop smaller centres outside the main downtown area. Several European cities have done this, and their centres are much less crowded.`],
  ['Do you think people will continue to move to cities in the future?', `Probably yes, because cities offer more jobs and services. However, remote working might encourage some to move to smaller towns, where life is cheaper and calmer. I think the overall trend will continue for now, although the pattern may become more balanced. It might take several decades, though, before the change becomes noticeable.`]]);
add('travel and journeys', 3, [
  ['Is the journey or the destination more important when travelling?', `For me, the journey can be just as important. Travelling by train or on foot allows you to see the landscape and meet people, so it becomes part of the experience. But for some trips, such as a business meeting, speed is more important, and the destination is all that matters. So the answer really depends on the purpose of the trip.`],
  ['How has transport changed the way people live?', `It has made it possible to live far from where we work, to trade goods across the world and to visit family abroad. Cities have grown outwards because of cars and trains. On the other hand, traffic and pollution have become major problems, so we now need cleaner forms of transport. Electric buses and trains are already a step in that direction.`],
  ['Will people travel more or less in the future?', `I think it will be a mixture. Many will continue to travel because they enjoy it, and incomes are rising in many countries. However, concerns about climate change and the rise of video meetings may reduce business travel and encourage people to take fewer, longer trips. However, holidays are so popular that I doubt the total number will fall sharply.`]]);
add('making decisions', 4, [
  ['What factors influence people when they make big decisions?', `Money, family and personal values are usually the most important. People also consider risk, which depends on their personality and responsibilities. Advice from others has an influence, as does emotion, though people may not admit it. The best decisions usually combine facts with a sense of what feels right.`],
  ['Is it better to make decisions quickly or to take time to think?', `For big decisions, I'd say take time, because it's easy to overlook consequences when you rush. For small matters, deciding quickly saves energy. Too much thinking can also lead to anxiety and delay, so it helps to set a deadline for yourself. That way, you give the decision proper thought without letting it drag on.`],
  ['Should young people be allowed to make their own life choices, even if their parents disagree?', `Within reason, yes. Young adults need to take responsibility, and learning from their own mistakes is part of growing up. Parents, however, often have wisdom and should be listened to. The ideal situation is an open discussion where parents give their views, but the final choice belongs to the young person.`]]);

// ---------- activity ----------
add('hobbies and leisure time', 2, [
  ['Why is it important for people to have hobbies?', `Hobbies give people a break from work and a source of pleasure that doesn't depend on achievement. They help reduce stress and may also develop new skills. Many people meet friends through hobbies, which prevents loneliness. For instance, I know several retired people who found their social life through a choir.`],
  ['Do people have as much free time as they did in the past?', `On paper, working hours are shorter than they were a century ago. In practice, many people feel they have less time because of long commutes, family duties and the habit of checking messages. Free time exists, but it's often fragmented, which makes it harder to enjoy fully. As a result, a free Sunday may feel shorter than it actually is.`],
  ['Should hobbies be turned into jobs?', `It can be wonderful if you manage it, but there's a risk. Once you depend on a hobby for money, it can become stressful, and you may lose the joy. Some people prefer to keep a hobby separate, so that it remains a pure escape from work. There isn't a single right answer, though, and it depends on the person.`]]);
add('outdoor activities and nature', 3, [
  ['Why are outdoor activities good for people?', `They combine exercise with fresh air and natural light, which improve both physical and mental health. Being in nature is also known to reduce stress. In groups, outdoor activities build friendships and teamwork. A weekend hiking club is a good example of this.`],
  ['Do people in cities have enough opportunities to enjoy nature?', `Often not. Parks may be crowded or far away, and many people lack time. Some cities are responding by planting trees along streets, creating green roofs and building cycling routes towards the countryside. Public transport to natural areas would help too.`],
  ['Is it dangerous to do outdoor activities without experience?', `It can be. Weather changes quickly in mountains, and beginners may get lost or injured. However, with preparation, such as checking forecasts, carrying water and telling someone the route, the risks are manageable. Joining a group or a club is a safe way to start.`]]);
add('health and fitness', 3, [
  ['Why do many people find it hard to stay healthy?', `Modern life makes the unhealthy choice easy. We sit for long hours, and processed food is cheap and convenient. People also lack time and motivation after work. Breaking old habits requires effort, and results appear slowly, so it's easy to give up.`],
  ['Who is responsible for people\'s health, individuals or governments?', `Both. Individuals decide what to eat and whether to exercise, but governments shape the environment, for example through food labelling, sports facilities and taxes on sugary drinks. If governments make healthy options accessible, more people will choose them. For example, cheap public swimming pools make it far easier for ordinary families to exercise.`],
  ['Will people be healthier in the future?', `Medical science will certainly improve, and wearable devices may help people to monitor their health. On the other hand, sedentary lifestyles and stress could cancel out some of those benefits. So the outcome will depend on whether people change their habits, not only on technology. In other words, technology can help, but it cannot do the exercise for us.`]]);
add('childhood games and play', 2, [
  ['How have children\'s games changed over time?', `Children used to play outdoors with simple things like balls, sticks and chalk. Now many play on screens, even with friends who are not in the same room. Outdoor play has declined in cities because of traffic and safety worries. Some traditional games are still played at school, though.`],
  ['Is playing important for children\'s development?', `Yes, it's essential. Play develops physical skills, creativity and social skills such as sharing and negotiating. Children also learn to solve problems and manage emotions through imaginative games. That's why unstructured play should be protected, not replaced by extra lessons.`],
  ['Are video games good or bad for children?', `Both, depending on how they are used. Some games improve problem-solving and teamwork, but too much screen time can harm sleep and attention and reduce physical activity. Parents should set limits and choose suitable games, ideally playing together occasionally. That way, parents can also see what their children enjoy.`]]);
add('lifelong learning', 3, [
  ['Why do some people continue to learn new skills throughout their lives?', `Curiosity is a big factor, and so is the need to adapt to a changing world of work. Others learn for pleasure, such as languages or music, to keep their minds active. Learning also provides a sense of purpose, which is especially valuable after retirement. Not everyone has this motivation, though, and some people simply prefer to relax.`],
  ['Is it better to learn skills in a class or by yourself?', `A class provides structure, feedback and the motivation of other learners, which is useful for beginners. Self-study offers flexibility and costs less, but it requires discipline. Many people combine both, using online resources between lessons. I've found that this mixture keeps me motivated best.`],
  ['Should employers pay for staff training?', `I think so, as it benefits both sides. Staff become more capable, and the company gets better results and may keep its employees longer. Some employers worry that trained staff will leave, but offering development usually increases loyalty rather than reducing it. Some studies in one country have suggested the same, although the evidence is not conclusive.`]]);
add('volunteering and community', 4, [
  ['Why do people volunteer?', `Many want to help others or support a cause they care about. Others hope to gain experience, meet people or feel part of a community. Volunteering also gives a sense of meaning, which paid work does not always provide. Retired people, for example, often say that volunteering gives structure to their week.`],
  ['Should volunteering be compulsory for students?', `I'm in two minds. Compulsory programmes introduce students to experiences they might not choose, and many then continue willingly. However, forcing people can reduce the real spirit of volunteering and breed resentment. A better approach may be to encourage it strongly and offer recognition rather than require it.`],
  ['Can volunteers replace paid workers?', `They can supplement but shouldn't replace them. Volunteers may lack training or may not be available consistently, so essential services need professionals. If volunteers took paid jobs, it could also harm employment. Their greatest value is in adding extra help and community spirit.`]]);

// ---------- media ----------
add('cinema and entertainment', 2, [
  ['Why do people enjoy watching films?', `Films offer a way to escape from everyday worries and to experience other lives. They combine story, music and images in a powerful way, and they can make people laugh or cry. Going to the cinema is also a social event. For many families, it's a regular treat.`],
  ['Will cinemas disappear because of streaming services?', `I don't think they'll disappear, but they may change. Streaming is convenient and cheap, so many people watch at home. However, the big screen and the shared atmosphere cannot be copied, so cinemas may focus on big events and special experiences. Cinemas that offer comfortable seats and good food are already doing well.`],
  ['Do films influence the way people think and behave?', `Yes, they can. Films shape our ideas about other cultures, fashion, relationships and even careers. Young people are especially influenced. This can be positive if it inspires, but it can also reinforce stereotypes, so viewers should think critically.`]]);
add('television and viewing habits', 3, [
  ['How has the way people watch television changed?', `People now choose what and when to watch through streaming services, rather than following a fixed schedule. They watch on phones, tablets and laptops as well as TVs. As a result, shared viewing has become less common, although big events like sports finals still bring people together. In my family, the whole household gathers for a big match.`],
  ['Is television an effective way to educate people?', `It can be, especially with documentaries that show things people can't see in real life, such as the deep ocean. Visuals and stories help people to remember. However, television is passive, so it works best alongside other forms of learning like reading and discussion. Therefore, I'd treat it as a starting point and not the whole lesson.`],
  ['Should the government control what is shown on television?', `Some control is sensible, for example to protect children from violent or unsuitable content and to prevent hate speech. But too much control can limit freedom of expression and allow the government to manage information. A system of age ratings and independent regulators seems a good compromise. In this way, parents and professionals share the responsibility.`]]);
add('apps and digital tools', 3, [
  ['Why are apps so popular?', `They are convenient, quick to use and often free. Apps can do almost anything, from ordering food to learning a language, and they're always in our pocket. Good design also makes them enjoyable, so people use them regularly. That said, convenience can also make people use them without thinking.`],
  ['Can apps replace traditional classroom learning?', `Not completely. Apps are great for practice and flexibility, but they can't offer the human interaction, feedback and motivation that a teacher gives. I think the best approach is blended learning, where apps support classroom lessons instead of replacing them. Some schools are already trying this, and the early results look promising.`],
  ['Are there any dangers in using apps too much?', `Yes. Many apps are designed to keep us engaged, which can lead to distraction and less sleep. They also collect personal information, so privacy is a concern. Users should check settings, limit notifications and take regular breaks from their devices.`]]);
add('online information', 3, [
  ['How can people tell whether online information is reliable?', `They should check who published it and whether other trusted sources say the same. Articles that name their sources and show the date are usually more reliable. Extreme headlines or requests to share quickly are warning signs. Taking a few minutes to check can prevent the spread of false information.`],
  ['Should schools teach students how to use the internet critically?', `Definitely. Students use the internet daily, but many don't know how to evaluate what they find. Lessons on checking sources, spotting adverts and protecting privacy would be as valuable as many traditional subjects. It's a basic skill for modern citizens.`],
  ['Is too much information a problem?', `It can be, since we're overwhelmed by notifications and news, and it is hard to concentrate or decide what is important. Choosing a few trusted sources and setting limited times for checking news helps. Quality matters more than quantity. I think this is a skill that people will need more and more.`]]);
add('music and culture', 3, [
  ['Why is music important in all cultures?', `Music expresses emotion and tells stories, and it's used in celebrations, religion and daily life. It brings people together, for instance at weddings and festivals, and it passes traditions between generations. It seems to be a universal human need. Even very small communities, with no writing, have their own songs.`],
  ['How has technology changed the way people listen to music?', `Streaming has given people access to millions of songs instantly and cheaply, and anyone can publish their own music online. On the other hand, artists earn less per play, and people tend to listen to single songs rather than whole albums. Live music has become more important to musicians' income. This is why concert tickets have become more expensive in many countries.`],
  ['Should children learn to play a musical instrument at school?', `I think so. It develops discipline, memory and coordination, and it gives children a creative outlet. Not every child will become a musician, but the experience of making music is valuable in itself. Schools should provide instruments for those who cannot afford them.`]]);
add('photography and memories', 4, [
  ['Why do people take so many photographs nowadays?', `Because cameras are in every phone and sharing is instant and free. People want to record special moments, but also to share their experiences on social media. The risk is that they spend so much time photographing that they don't fully enjoy the moment. For example, many people at concerts watch the whole show through their phone screens.`],
  ['Do photographs give an accurate picture of reality?', `Not always. A photograph shows one moment from one angle, and it can be edited or posed. Filters and editing apps change how people and places look. So a photograph can be true in a literal sense but misleading in its overall impression.`],
  ['How might photography change in the future?', `Phones are already improving, and artificial intelligence can correct or even create images. This will make it harder to know whether a picture is real, so people may need new ways to check authenticity. At the same time, I expect that simple, honest photos of family and friends will continue to matter most. In the end, a photograph is valuable because of the memory it carries.`]]);

const items = P.map((p, i) => ({
  id: 'sp3-' + String(i + 1).padStart(2, '0'), type: 'open', level: p.level, exams: ['academic', 'general'],
  facets: { skill: 'speaking', part: '3', qtype: 'discussion' }, sub: SUBS[i],
  q: `<p><b>Discussion linked to Part 2: ${p.theme}</b></p><ol>${p.qa.map(([q]) => `<li>${q}</li>`).join('')}</ol><p>Give a developed answer to each question: your position, a reason, an example, and a contrast or qualification.</p>`,
  timers: { speak: 180 },
  model: p.qa.map(([q, a]) => `<p><b>${q}</b><br>${a}</p>`).join(''),
  checklist: ['You gave a clear position in the first sentence', 'You supported it with a reason, not just an opinion', 'You gave a real example (a person, a country, a situation)', 'You showed another side (however, on the other hand, although)', 'You used speculating language (might, is likely to, would probably) where you were not sure'],
}));
export default { topic: 'speaking-part3', items };
